-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. DROP TABLES IN ORDER
DROP TABLE IF EXISTS transaction_details CASCADE;
DROP TABLE IF EXISTS transaction_payments CASCADE;
DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS stock_movements CASCADE;
DROP TABLE IF EXISTS product_units CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS cashier_shifts CASCADE;
DROP TABLE IF EXISTS shopee_orders CASCADE;
DROP TABLE IF EXISTS ml_association_rules CASCADE;
DROP TABLE IF EXISTS members CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS roles CASCADE;
DROP TABLE IF EXISTS stores CASCADE;

-- 3. CREATE TABLES
CREATE TABLE stores (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(150) NOT NULL,
    address TEXT,
    phone VARCHAR(50),
    point_spend_per_point INT DEFAULT 10000,
    point_value_per_point NUMERIC DEFAULT 100,
    allow_negative_stock BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE roles (
    id SERIAL PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    role_id INT NOT NULL REFERENCES roles(id),
    username VARCHAR(50) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(100) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE members (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone_number VARCHAR(20) NOT NULL UNIQUE,
    full_name VARCHAR(100) NOT NULL,
    points INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug VARCHAR(100) UNIQUE NOT NULL,
    name VARCHAR(100) NOT NULL,
    shopee_category_id BIGINT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE products (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    category_id UUID REFERENCES categories(id) ON DELETE RESTRICT,
    sku VARCHAR(100) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    price NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    cost_price NUMERIC(12, 2) DEFAULT 0.00,
    stock INT NOT NULL DEFAULT 0,
    unit VARCHAR(20) DEFAULT 'pcs',
    is_active BOOLEAN DEFAULT TRUE,
    shopee_item_id BIGINT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE product_units (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    unit_name VARCHAR(20) NOT NULL DEFAULT 'Pcs',
    conversion_factor INT NOT NULL DEFAULT 1,
    price NUMERIC(12, 2) NOT NULL,
    barcode VARCHAR(100) UNIQUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (product_id, unit_name)
);

CREATE TABLE stock_movements (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    reference_type VARCHAR(50) NOT NULL,
    reference_id UUID NULL,
    qty_base_change INT NOT NULL,
    balance_after INT NOT NULL,
    unit_cost_snapshot NUMERIC(12, 2) DEFAULT 0.00,
    created_by UUID NULL,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE cashier_shifts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    user_id UUID NOT NULL REFERENCES users(id),
    opened_at TIMESTAMPTZ DEFAULT NOW(),
    closed_at TIMESTAMPTZ NULL,
    starting_cash NUMERIC(15, 2) DEFAULT 0.00,
    expected_cash NUMERIC(15, 2) DEFAULT 0.00,
    actual_cash NUMERIC(15, 2) NULL,
    cash_difference NUMERIC(15, 2) NULL,
    status VARCHAR(20) DEFAULT 'OPEN'
);

CREATE TABLE transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    user_id UUID NOT NULL REFERENCES users(id),
    member_id UUID REFERENCES members(id) ON DELETE SET NULL,
    shift_id UUID REFERENCES cashier_shifts(id) ON DELETE SET NULL,
    receipt_number VARCHAR(60) NOT NULL UNIQUE,
    total_amount NUMERIC(15, 2) NOT NULL,
    subtotal_amount NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    discount_amount NUMERIC(15, 2) DEFAULT 0.00,
    payment_method VARCHAR(30) NOT NULL DEFAULT 'CASH',
    payment_reference VARCHAR(100),
    points_earned INT DEFAULT 0,
    points_redeemed INT DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'COMPLETED',
    idempotency_key VARCHAR(100) NULL,
    channel VARCHAR(30) DEFAULT 'POS',
    external_order_sn VARCHAR(100) NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE transaction_details (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    transaction_id UUID NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    product_id UUID NOT NULL REFERENCES products(id),
    unit_id UUID NULL REFERENCES product_units(id),
    qty INT NOT NULL,
    conversion_factor INT NOT NULL DEFAULT 1,
    base_qty INT NOT NULL DEFAULT 1,
    price_per_unit NUMERIC(12, 2) NOT NULL,
    cost_price_snapshot NUMERIC(12, 2) DEFAULT 0.00,
    subtotal NUMERIC(15, 2) NOT NULL
);

CREATE TABLE transaction_payments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    transaction_id UUID NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    payment_method VARCHAR(30) NOT NULL,
    amount NUMERIC(15, 2) NOT NULL,
    payment_reference VARCHAR(100),
    change_given NUMERIC(15, 2) DEFAULT 0.00,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE shopee_orders (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_sn VARCHAR(100) NOT NULL UNIQUE,
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    buyer_username VARCHAR(100) NOT NULL,
    order_status VARCHAR(50) NOT NULL DEFAULT 'READY_TO_SHIP',
    shipping_carrier VARCHAR(100),
    tracking_number VARCHAR(100),
    total_amount NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    shopee_escrow_amount NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    items JSONB NOT NULL DEFAULT '[]',
    stock_deducted BOOLEAN DEFAULT FALSE,
    shopee_created_at TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE ml_association_rules (
    id SERIAL PRIMARY KEY,
    antecedent_product_ids JSONB NOT NULL,
    consequent_product_ids JSONB NOT NULL,
    support NUMERIC(6, 4) NOT NULL,
    confidence NUMERIC(6, 4) NOT NULL,
    lift NUMERIC(10, 4) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- INDEXES FOR INSTANT LOOKUPS
CREATE INDEX idx_products_sku ON products(sku);
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_product_units_barcode ON product_units(barcode);
CREATE INDEX idx_transactions_created ON transactions(created_at);
CREATE INDEX idx_stock_movements_product ON stock_movements(product_id);

